            ans = max(ans, base + abs(nums[n - 1] - nums[k - 1]) - abs(nums[k - 1] - nums[k]))
        best = 0
        maxHi, minLo = float('-inf'), float('inf')
        for k in range(n - 1):
            lo, hi = min(nums[k], nums[k + 1]), max(nums[k], nums[k + 1])
            if k > 0:
                best = max(best, min(hi, maxHi) - max(lo, minLo))
            maxHi, minLo = max(maxHi, hi), min(minLo, lo)
        return max(ans, base + 2 * best)

